'use strict';

const ORDER_EDITOR_CHANNELS=['Facebook','LINE OA','Offline sales','Review'];
const ORDER_EDITOR_MARKETPLACE_CHANNELS=['Shopee','Lazada','TikTok Shop'];
const ORDER_EDITOR_CARRIERS=['Flash Express','J&T Express','KEX','ไปรษณีย์ไทย','อื่น ๆ'];
const ORDER_EDITOR_PROVINCES=['กรุงเทพมหานคร','กระบี่','กาญจนบุรี','กาฬสินธุ์','กำแพงเพชร','ขอนแก่น','จันทบุรี','ฉะเชิงเทรา','ชลบุรี','ชัยนาท','ชัยภูมิ','ชุมพร','เชียงราย','เชียงใหม่','ตรัง','ตราด','ตาก','นครนายก','นครปฐม','นครพนม','นครราชสีมา','นครศรีธรรมราช','นครสวรรค์','นนทบุรี','นราธิวาส','น่าน','บึงกาฬ','บุรีรัมย์','ปทุมธานี','ประจวบคีรีขันธ์','ปราจีนบุรี','ปัตตานี','พระนครศรีอยุธยา','พะเยา','พังงา','พัทลุง','พิจิตร','พิษณุโลก','เพชรบุรี','เพชรบูรณ์','แพร่','ภูเก็ต','มหาสารคาม','มุกดาหาร','แม่ฮ่องสอน','ยโสธร','ยะลา','ร้อยเอ็ด','ระนอง','ระยอง','ราชบุรี','ลพบุรี','ลำปาง','ลำพูน','เลย','ศรีสะเกษ','สกลนคร','สงขลา','สตูล','สมุทรปราการ','สมุทรสงคราม','สมุทรสาคร','สระแก้ว','สระบุรี','สิงห์บุรี','สุโขทัย','สุพรรณบุรี','สุราษฎร์ธานี','สุรินทร์','หนองคาย','หนองบัวลำภู','อ่างทอง','อำนาจเจริญ','อุดรธานี','อุตรดิตถ์','อุทัยธานี','อุบลราชธานี'];
const orderDigits=value=>String(value||'').replace(/[๐-๙]/g,c=>String(c.charCodeAt(0)-3664));
const orderPhone=value=>orderDigits(value).replace(/[\s().-]/g,'');
const orderAmount=value=>round(Number(value)||0);
function orderLocalTime(value=new Date()){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(p=>[p.type,p.value]));return parts.year+'-'+parts.month+'-'+parts.day+'T'+parts.hour+':'+parts.minute}
function orderEditorDialogClass(name){const dialog=document.getElementById('dialog');dialog.classList.remove('order-editor-dialog','order-detail-dialog');dialog.classList.add(name);dialog.addEventListener('close',()=>dialog.classList.remove(name),{once:true})}
function orderAddressFields(prefix,address={},required=true){return `<div class="oe-address-grid"><label class="field oe-span-2">บ้านเลขที่ / อาคาร / ถนน<textarea name="${prefix}AddressLine" rows="2" maxlength="300" ${required?'required':''} autocomplete="${prefix==='shipping'?'shipping':'billing'} address-line1" placeholder="บ้านเลขที่ หมู่บ้าน อาคาร ซอย และถนน">${esc(address.addressLine||'')}</textarea></label><label class="field">แขวง / ตำบล<input name="${prefix}Subdistrict" value="${esc(address.subdistrict||'')}" maxlength="80" ${required?'required':''}></label><label class="field">เขต / อำเภอ<input name="${prefix}District" value="${esc(address.district||'')}" maxlength="80" ${required?'required':''}></label><label class="field">จังหวัด<input name="${prefix}Province" value="${esc(address.province||'')}" maxlength="80" list="order-provinces" ${required?'required':''} placeholder="เลือกหรือพิมพ์จังหวัด"></label><label class="field">รหัสไปรษณีย์<input name="${prefix}PostalCode" value="${esc(address.postalCode||'')}" inputmode="numeric" maxlength="5" ${required?'required':''} autocomplete="${prefix==='shipping'?'shipping':'billing'} postal-code" placeholder="5 หลัก"></label></div>`}
function orderEditorSection(number,title,subtitle,content){return `<section class="oe-section"><div class="oe-section-heading"><span>${number}</span><div><h3>${title}</h3><p>${subtitle}</p></div></div>${content}</section>`}
function orderEditorAddress(form,prefix){return {addressLine:String(form.elements[prefix+'AddressLine'].value).trim(),subdistrict:String(form.elements[prefix+'Subdistrict'].value).trim(),district:String(form.elements[prefix+'District'].value).trim(),province:String(form.elements[prefix+'Province'].value).trim(),postalCode:orderDigits(form.elements[prefix+'PostalCode'].value).trim()}}
function orderEditorTotals(items,discount,shippingFee){const subtotal=round(sum(items,line=>(Number(line.qty)||0)*(Number(line.price)||0))),lineDiscount=round(sum(items,line=>Number(line.discount)||0)),itemNetTotal=round(subtotal-lineDiscount);return {subtotal,lineDiscount,itemNetTotal,discount:orderAmount(discount),shippingFee:orderAmount(shippingFee),grandTotal:round(itemNetTotal-orderAmount(discount)+orderAmount(shippingFee))}}
function orderAddressText(address,fallback=''){if(!address)return fallback;return [address.addressLine,address.subdistrict,address.district,address.province,address.postalCode].filter(Boolean).join(' ')}
function openManualOrderEditor(existing=null){
  const editing=!!existing,action=editing?'update-order':'create-order';
  if(currentAuth?.role!=='admin'||!canAction(action)){toast('เฉพาะ Admin ที่มีสิทธิ์เท่านั้น');return}
  if(editing&&!['new','hold','ready'].includes(existing.status)){toast('แก้ไขได้ก่อนเริ่มแพ็กสินค้าเท่านั้น');return}
  const requestId=crypto.randomUUID(),source=existing||{},shipping=source.shippingAddress||{province:source.province||''},billingSame=source.billingSame!==false;
  const editor={items:editing?source.items.map(line=>({sku:line.sku,qty:line.qty,price:Number(line.price)||0,discount:Number(line.discount)||0})):(PRODUCTS[0]?[{sku:PRODUCTS[0].sku,qty:1,price:PRODUCTS[0].price||0,discount:0}]:[]),pending:false,lastReview:source.channel==='Review'};
  const payment=source.payment||{method:'unpaid',status:'pending',amount:0},channel=source.channel||'Facebook',channelLocked=editing&&ORDER_EDITOR_MARKETPLACE_CHANNELS.includes(channel),channelOptions=channelLocked?[channel]:ORDER_EDITOR_CHANNELS;
  const customerFields=`<div class="oe-field-grid"><label class="field">ช่องทางรับออเดอร์<select name="channel" ${channelLocked?'disabled':''}>${channelOptions.map(name=>`<option value="${esc(name)}" ${channel===name?'selected':''}>${esc(name)}</option>`).join('')}</select>${channelLocked?'<span class="form-help">คงช่องทางเดิมจาก Marketplace</span>':''}</label><label class="field">วันและเวลารับออเดอร์<input name="createdAt" type="datetime-local" value="${esc(editing?orderLocalTime(source.createdAt||source.date+'T'+(source.time||'12:00')+':00+07:00'):orderLocalTime())}"><span class="form-help">เวลาประเทศไทย</span></label><label class="field">ชื่อผู้รับ <span class="oe-required">*</span><input name="customer" value="${esc(source.customer||'')}" maxlength="80" autocomplete="name" required placeholder="ชื่อและนามสกุลผู้รับ"></label><label class="field">เบอร์โทรศัพท์ <span class="oe-required">*</span><input name="phone" value="${esc(source.phone||'')}" type="tel" maxlength="30" autocomplete="tel" required placeholder="0812345678 หรือ +66812345678"></label><label class="field">อีเมล (ถ้ามี)<input name="email" value="${esc(source.email||'')}" type="email" maxlength="120" autocomplete="email" placeholder="name@example.com"></label><label class="field">ชื่อบัญชีโซเชียล (ถ้ามี)<input name="socialName" value="${esc(source.socialName||'')}" maxlength="100" placeholder="ชื่อ Facebook หรือ LINE"></label><label class="field oe-span-2">ลิงก์บัญชีโซเชียล (ถ้ามี)<input name="socialUrl" value="${esc(source.socialUrl||'')}" type="url" maxlength="500" placeholder="https://..."></label></div>`;
  const shippingFields=`${orderAddressFields('shipping',shipping)}<div class="oe-field-grid oe-subsection"><label class="field">ขนส่ง<select name="carrier">${[...new Set([...ORDER_EDITOR_CARRIERS,...(source.carrier?[source.carrier]:[])])].map(name=>`<option ${source.carrier===name?'selected':''}>${name}</option>`).join('')}</select></label><label class="field">ค่าจัดส่งที่เรียกเก็บ (บาท)<input name="shippingFee" type="number" min="0" max="1000000" step="0.01" value="${Number(source.shippingFee)||0}" required></label></div><label class="oe-checkbox"><input name="billingSame" type="checkbox" ${billingSame?'checked':''}><span>ใช้ที่อยู่จัดส่งเป็นที่อยู่ออกบิล</span></label><div id="oe-billing-address" class="oe-billing" ${billingSame?'hidden':''}><h4>ที่อยู่ออกบิล</h4>${orderAddressFields('billing',source.billingAddress||{},!billingSame)}</div>`;
  const paymentFields=`<div class="oe-field-grid"><label class="field">วิธีชำระเงิน<select name="paymentMethod"><option value="unpaid" ${payment.method==='unpaid'?'selected':''}>ยังไม่ชำระ / รอเลือกวิธี</option><option value="transfer" ${payment.method==='transfer'?'selected':''}>โอนเงิน</option><option value="cod" ${payment.method==='cod'?'selected':''}>เก็บเงินปลายทาง (COD)</option><option value="free" ${payment.method==='free'?'selected':''} disabled>ส่งฟรีสำหรับ Review</option></select></label><label class="field">สถานะการชำระ<select name="paymentStatus"><option value="pending" ${payment.status!=='confirmed'?'selected':''}>รอตรวจ / ยังไม่ได้รับเงิน</option><option value="confirmed" ${payment.status==='confirmed'?'selected':''}>ยืนยันรับเงินด้วยตนเอง</option></select></label><label class="field">ยอดรับชำระที่บันทึก (บาท)<input name="paymentAmount" type="number" min="0" max="10000000" step="0.01" value="${Number(payment.amount)||0}" required><button type="button" class="text-btn oe-fill-total" id="oe-use-total">ใช้ยอดที่ต้องชำระ</button></label><label class="field">วันและเวลาที่ชำระ<input name="paymentPaidAt" type="datetime-local" value="${esc(payment.paidAt?orderLocalTime(payment.paidAt):'')}"></label><label class="field">ธนาคาร / บัญชีรับเงิน (ถ้ามี)<input name="paymentBank" maxlength="100" value="${esc(payment.bankName||'')}" placeholder="ข้อมูลที่ตรวจสอบเอง"></label><label class="field">เลขอ้างอิงการชำระ (ถ้ามี)<input name="paymentReference" maxlength="120" value="${esc(payment.reference||'')}" placeholder="เลขอ้างอิงรายการโอน"></label></div><div id="oe-payment-confirm" class="oe-payment-confirm" hidden><label class="oe-checkbox"><input id="oe-confirm-payment" type="checkbox" ${payment.status==='confirmed'?'checked':''}><span>ฉันตรวจสอบการรับเงินจริงด้วยตนเองแล้ว</span></label></div><div class="oe-info" id="oe-payment-note">บันทึกผลตรวจสอบโดยผู้ใช้งาน ระบบยังไม่ตรวจสลิปหรือยืนยันรายการกับธนาคาร</div>`;
  const itemsFields=`<label class="field">ค้นหาและเพิ่มสินค้า<div class="oe-product-search">${icon('search')}<input type="search" id="oe-product-search" placeholder="พิมพ์ชื่อสินค้า หรือ SKU" autocomplete="off"></div></label><div id="oe-product-results" class="oe-product-results"></div><div id="oe-item-list"></div><p class="form-help oe-item-note">เพิ่มสินค้าเดิมจะรวมจำนวนในบรรทัดเดียว · สูงสุด 50 SKU ต่อออเดอร์</p>`;
  const summary=`<aside class="oe-summary"><div class="oe-summary-title">${icon('wallet')}<h3>สรุปคำสั่งซื้อ</h3></div><div id="oe-summary-values"></div><label class="field oe-order-discount">ส่วนลดทั้งออเดอร์ (บาท)<input name="discount" type="number" min="0" max="10000000" step="0.01" value="${Number(source.discount)||0}" required></label><div class="oe-grand-total"><span>ยอดที่ต้องชำระ</span><strong id="oe-grand-total">—</strong><small>หลังส่วนลด รวมค่าจัดส่ง</small></div><div id="oe-stock-note" class="oe-info"></div><div class="auth-error" id="form-error" role="alert"></div><button class="btn primary oe-submit" type="submit">${editing?'บันทึกการแก้ไข':'สร้างออเดอร์'}</button><p class="form-help">${editing&&source.reserved?'ระบบจะตรวจและปรับจำนวนที่กันไว้พร้อมกัน หากสินค้าไม่พอจะเก็บออเดอร์เดิมไว้':'ออเดอร์ขายยังไม่กันสต๊อกจนกดรับเข้าคิว ส่วน Review กันสต๊อกทันที'}</p></aside>`;
  modal(editing?'แก้ไขออเดอร์ '+esc(source.id):'สร้างคำสั่งซื้อ',esc((currentStore?.name||'ร้านปัจจุบัน')+' · ข้อมูลลูกค้า การจัดส่ง และการชำระเงิน'),`<form id="new-order-form" class="oe-form"><datalist id="order-provinces">${ORDER_EDITOR_PROVINCES.map(name=>`<option value="${name}">`).join('')}</datalist><div class="oe-layout"><div class="oe-main">${orderEditorSection('01','ข้อมูลลูกค้า','ระบุผู้รับและช่องทางที่ลูกค้าติดต่อมา',customerFields)}${orderEditorSection('02','ที่อยู่จัดส่ง','กรอกให้ครบเพื่อให้ทีมคลังเตรียมจัดส่งได้',shippingFields)}${orderEditorSection('03','การชำระเงิน','แยกยอดที่ต้องชำระออกจากยอดรับเงินที่บันทึก',paymentFields)}${orderEditorSection('04','สินค้าในออเดอร์','เลือกได้หลายสินค้า ใช้สต๊อกกลางของร้านนี้',itemsFields)}${orderEditorSection('05','หมายเหตุเพิ่มเติม','ข้อมูลให้ทีมทำงานต่อได้ครบถ้วน',`<div class="oe-field-grid"><label class="field oe-span-2">หมายเหตุ<textarea name="notes" rows="3" maxlength="1000" placeholder="รายละเอียดเพิ่มเติมสำหรับทีม">${esc(source.notes||'')}</textarea></label><label class="field oe-span-2">แท็ก (ถ้ามี)<input name="tags" maxlength="200" value="${esc(Array.isArray(source.tags)?source.tags.join(', '):source.tags||'')}" placeholder="เช่น ลูกค้าใหม่, ส่งด่วน"></label></div>`)}</div>${summary}</div></form>`);
  orderEditorDialogClass('order-editor-dialog');
  const form=document.getElementById('new-order-form'),field=name=>form.elements[name],isReview=()=>field('channel').value==='Review';
  function renderResults(){const query=document.getElementById('oe-product-search').value.trim().toLowerCase();const found=PRODUCTS.filter(p=>[p.sku,p.name,p.sub].join(' ').toLowerCase().includes(query)).slice(0,12);document.getElementById('oe-product-results').innerHTML=found.map(p=>`<button type="button" class="oe-product-result" data-editor-add="${esc(p.sku)}"><span class="product-icon">${esc(p.sku.slice(0,3))}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · พร้อมขาย ${num(available(p.sku))} ชิ้น</small></span><span class="oe-product-add">+ เพิ่ม</span></button>`).join('')||'<p class="oe-empty">ไม่พบสินค้า ลองค้นด้วยชื่อหรือ SKU</p>';document.querySelectorAll('[data-editor-add]').forEach(btn=>btn.onclick=()=>{if(editor.pending)return;const product=PRODUCTS.find(p=>p.sku===btn.dataset.editorAdd),line=editor.items.find(l=>l.sku===product.sku);if(line){if(line.qty>=100){toast('สินค้าแต่ละรายการเพิ่มได้ไม่เกิน 100 ชิ้น');return}line.qty++}else{if(editor.items.length>=50){toast('หนึ่งออเดอร์เพิ่มได้ไม่เกิน 50 SKU');return}editor.items.push({sku:product.sku,qty:1,price:isReview()?0:product.price,discount:0})}renderItems();renderSummary()})}
  function renderItems(){document.getElementById('oe-item-list').innerHTML=editor.items.length?`<div class="oe-items-head"><span>สินค้า</span><span>จำนวน</span><span>ราคา / ชิ้น</span><span>ส่วนลดรายการ</span><span>รวม</span><span></span></div>${editor.items.map((line,index)=>{const p=PRODUCTS.find(p=>p.sku===line.sku);return `<div class="oe-item" data-item-row="${esc(line.sku)}"><div class="oe-item-name"><strong>${esc(p?.name||line.sku)}</strong><small>${esc(line.sku)} · ${esc(p?.location||'')}</small></div><label class="field"><span class="oe-mobile-label">จำนวน</span><input name="itemQty" aria-label="จำนวน ${esc(line.sku)}" data-line-field="qty" data-line-sku="${esc(line.sku)}" type="number" min="1" max="100" step="1" required value="${line.qty}"></label><label class="field"><span class="oe-mobile-label">ราคา / ชิ้น</span><input name="itemPrice" aria-label="ราคาต่อชิ้น ${esc(line.sku)}" data-line-field="price" data-line-sku="${esc(line.sku)}" type="number" min="0" max="1000000" step="0.01" required value="${line.price}" ${isReview()?'disabled':''}></label><label class="field"><span class="oe-mobile-label">ส่วนลดรายการ</span><input name="itemDiscount" aria-label="ส่วนลดทั้งรายการ ${esc(line.sku)}" data-line-field="discount" data-line-sku="${esc(line.sku)}" type="number" min="0" max="${line.qty*line.price}" step="0.01" required value="${line.discount}" ${isReview()?'disabled':''}></label><strong class="oe-item-net" data-line-net="${esc(line.sku)}">${money(line.qty*line.price-line.discount)}</strong><button class="oe-remove" type="button" data-remove-line="${index}" aria-label="ลบ ${esc(line.sku)}">×</button></div>`}).join('')}`:'<div class="oe-empty">ยังไม่มีสินค้า ค้นหาสินค้าแล้วกดเพิ่ม</div>';document.querySelectorAll('[data-line-field]').forEach(input=>input.oninput=()=>{const line=editor.items.find(l=>l.sku===input.dataset.lineSku);line[input.dataset.lineField]=Number(input.value);const row=input.closest('[data-item-row]');row.querySelector('[data-line-field=discount]').max=line.qty*line.price;row.querySelector('[data-line-net]').textContent=money(line.qty*line.price-line.discount);renderSummary()});document.querySelectorAll('[data-remove-line]').forEach(btn=>btn.onclick=()=>{if(editor.pending)return;editor.items.splice(Number(btn.dataset.removeLine),1);renderItems();renderSummary()})}
  function renderSummary(){const totals=orderEditorTotals(editor.items,field('discount').value,field('shippingFee').value);document.getElementById('oe-summary-values').innerHTML=`<div class="stat-line"><span>สินค้า ${editor.items.length} รายการ / ${sum(editor.items,line=>Number(line.qty)||0)} ชิ้น</span><strong>${money(totals.subtotal)}</strong></div><div class="stat-line"><span>ส่วนลดรายสินค้า</span><strong>− ${money(totals.lineDiscount)}</strong></div><div class="stat-line"><span>ค่าสินค้าหลังลดรายสินค้า</span><strong>${money(totals.itemNetTotal)}</strong></div><div class="stat-line"><span>ค่าจัดส่ง</span><strong>${money(totals.shippingFee)}</strong></div>`;document.getElementById('oe-grand-total').textContent=money(totals.grandTotal);field('discount').max=Math.max(0,totals.itemNetTotal);field('paymentAmount').max=Math.max(0,totals.grandTotal);const missing=editor.items.filter(line=>{const old=source.reserved?(source.items||[]).find(l=>l.sku===line.sku)?.qty||0:0;return line.qty>available(line.sku)+old});document.getElementById('oe-stock-note').textContent=isReview()?(missing.length?'สินค้าไม่พอสำหรับ Review บางรายการ ต้องเติมสินค้าก่อนสร้างออเดอร์ส่งฟรี':'Review ส่งฟรี ไม่มีรายได้ และกันสินค้าจากสต๊อกกลางทันที'):missing.length?'จำนวนที่เลือกเกินสต๊อกพร้อมขายบางรายการ ต้องเติมสินค้าก่อนรับเข้าคิวจัดส่ง':'จำนวนพร้อมขายเป็นยอดกลางเดียวกับทุกช่องทางของร้าน';document.getElementById('oe-stock-note').classList.toggle('oe-warning',missing.length>0)}
  function updatePayment(){const review=isReview(),method=field('paymentMethod').value;if(review){field('paymentMethod').value='free';field('paymentStatus').value='confirmed';field('paymentAmount').value='0';field('paymentPaidAt').value='';field('paymentBank').value='';field('paymentReference').value=''}else if(method==='unpaid'){field('paymentStatus').value='pending';field('paymentAmount').value='0'}const confirmed=!review&&field('paymentStatus').value==='confirmed';field('paymentMethod').disabled=review;field('paymentStatus').disabled=review||field('paymentMethod').value==='unpaid';field('paymentAmount').disabled=review||field('paymentMethod').value==='unpaid';field('paymentPaidAt').disabled=review;field('paymentPaidAt').required=confirmed;field('paymentBank').disabled=review;field('paymentReference').disabled=review;document.getElementById('oe-use-total').disabled=review||field('paymentMethod').value==='unpaid';document.getElementById('oe-payment-confirm').hidden=!confirmed;document.getElementById('oe-confirm-payment').required=confirmed;document.getElementById('oe-payment-note').textContent=review?'Review เป็นการส่งฟรี ไม่มีการรับชำระเงิน':'บันทึกผลตรวจสอบโดยผู้ใช้งาน ระบบยังไม่ตรวจสลิปหรือยืนยันรายการกับธนาคาร'}
  function updateChannel(){field('channel').disabled=channelLocked;const review=isReview();if(review){for(const line of editor.items){line.price=0;line.discount=0}field('discount').value='0';field('shippingFee').value='0'}else if(editor.lastReview){for(const line of editor.items)line.price=PRODUCTS.find(p=>p.sku===line.sku)?.price||0;field('paymentMethod').value='unpaid';field('paymentStatus').value='pending'}editor.lastReview=review;field('discount').disabled=review;field('shippingFee').disabled=review;updatePayment();renderItems();renderSummary()}
  function updateBilling(){const same=field('billingSame').checked,box=document.getElementById('oe-billing-address');box.hidden=same;box.querySelectorAll('input,textarea').forEach(input=>{input.required=!same;input.disabled=same})}
  document.getElementById('oe-product-search').oninput=renderResults;
  document.getElementById('oe-use-total').onclick=()=>{field('paymentAmount').value=orderEditorTotals(editor.items,field('discount').value,field('shippingFee').value).grandTotal};
  field('channel').onchange=updateChannel;field('billingSame').onchange=updateBilling;field('paymentMethod').onchange=updatePayment;field('paymentStatus').onchange=updatePayment;
  for(const name of ['discount','shippingFee'])field(name).oninput=renderSummary;
  renderResults();updateBilling();updateChannel();
  form.onsubmit=async event=>{
    event.preventDefault();if(editor.pending)return;const error=document.getElementById('form-error');error.textContent='';
    try{
      if(!editor.items.length)throw Error('เพิ่มสินค้าอย่างน้อย 1 รายการ');
      for(const line of editor.items){if(!Number.isInteger(line.qty)||line.qty<1||line.qty>100)throw Error('จำนวนสินค้าต้องเป็นจำนวนเต็ม 1–100 ชิ้น');if(!Number.isFinite(line.price)||line.price<0||line.price>1000000||!Number.isFinite(line.discount)||line.discount<0||line.discount>line.qty*line.price)throw Error('ตรวจราคาและส่วนลดของแต่ละรายการ')}
      const shippingAddress=orderEditorAddress(form,'shipping'),billingAddress=field('billingSame').checked?null:orderEditorAddress(form,'billing');
      for(const address of [shippingAddress,billingAddress].filter(Boolean)){if(!address.addressLine||!address.subdistrict||!address.district||!address.province)throw Error('กรอกที่อยู่ให้ครบทุกช่อง');if(!/^\d{5}$/.test(address.postalCode))throw Error('รหัสไปรษณีย์ต้องเป็นตัวเลข 5 หลัก')}
      const phone=orderPhone(field('phone').value);if(!/^\+?\d{9,15}$/.test(phone))throw Error('กรอกเบอร์โทร 9–15 หลัก สามารถใช้ + รหัสประเทศได้');
      const totals=orderEditorTotals(editor.items,field('discount').value,field('shippingFee').value),review=isReview();
      if(totals.discount<0||totals.discount>totals.itemNetTotal||totals.shippingFee<0||totals.grandTotal<0)throw Error('ตรวจส่วนลดทั้งออเดอร์และค่าจัดส่ง');
      const paymentValue={method:review?'free':field('paymentMethod').value,status:review?'confirmed':field('paymentStatus').value,amount:review?0:orderAmount(field('paymentAmount').value),paidAt:review?'':field('paymentPaidAt').value,bankName:review?'':field('paymentBank').value.trim(),reference:review?'':field('paymentReference').value.trim()};
      if(paymentValue.amount<0||paymentValue.amount>totals.grandTotal)throw Error('ยอดรับชำระต้องไม่เกินยอดที่ต้องชำระ');
      if(!review&&paymentValue.status==='confirmed'&&!document.getElementById('oe-confirm-payment').checked)throw Error('ยืนยันว่าตรวจสอบการรับเงินจริงด้วยตนเองก่อน');
      const payload={...(editing?{id:source.id}:{}),requestId,channel:field('channel').value,customer:field('customer').value.trim(),phone,email:field('email').value.trim(),socialName:field('socialName').value.trim(),socialUrl:field('socialUrl').value.trim(),shippingAddress,billingSame:field('billingSame').checked,billingAddress,items:editor.items.map(line=>({sku:line.sku,qty:line.qty,price:review?0:orderAmount(line.price),discount:review?0:orderAmount(line.discount)})),discount:review?0:totals.discount,shippingFee:review?0:totals.shippingFee,carrier:field('carrier').value,createdAt:field('createdAt').value,payment:paymentValue,notes:field('notes').value.trim(),tags:field('tags').value.trim()};
      editor.pending=true;form.querySelectorAll('button,input,select,textarea').forEach(control=>control.disabled=true);const result=await runAction(action,payload);
      document.getElementById('dialog').close();Object.assign(state,{from:'',to:'',channel:'',product:'',province:'',status:result?.status||'all',q:'',page:1});await changeView('orders');toast(typeof result==='string'?result:result.message||(editing?'แก้ไขออเดอร์แล้ว':'สร้างออเดอร์แล้ว'));
    }catch(problem){editor.pending=false;if(form.isConnected){error.textContent=problem.message;form.querySelectorAll('button,input,select,textarea').forEach(control=>control.disabled=false);updateBilling();updateChannel();error.scrollIntoView({block:'nearest',behavior:'smooth'})}}
  };
}
newOrder=function(){openManualOrderEditor()};
function editOrder(id){const order=orders.find(o=>o.id===id);if(order)openManualOrderEditor(order)}
showOrder=function(id){
  if(!currentAuth)return;const order=orders.find(o=>o.id===id);if(!order)return;state.detailId=id;
  const financial=isFinanceVisible(),shipping=order.shippingAddress,payment=order.payment,totals=orderEditorTotals(order.items,order.discount,order.shippingFee);
  const next={new:['reserve','กันสต๊อก / เข้าคิวหยิบ'],ready:['start-pack','เริ่มแพ็ก'],packing:['open-pack','เปิดจุดแพ็ก'],packed:['dispatch','จำลองส่งมอบขนส่ง'],hold:['resolve','ตรวจและแก้ไข']};
  let actions='',n=next[order.status];if(n&&(canAction(n[0])||n[0]==='open-pack'&&canView('fulfillment')))actions+=button(n[1],n[0]==='start-pack'?'detail-pack':'detail-'+n[0],'','primary');
  if(canAction('cancel')&&['new','ready','packing','packed','hold'].includes(order.status))actions=button('ยกเลิกออเดอร์','detail-cancel','','danger')+actions;
  const edit=currentAuth.role==='admin'&&canAction('update-order')&&['new','hold','ready'].includes(order.status)?'<button type="button" class="btn" id="edit-order-details">แก้ไขข้อมูลออเดอร์</button>':'';
  const lines=order.items.map(line=>{const p=PRODUCTS.find(p=>p.sku===line.sku);return `<tr><td><strong>${esc(p?.name||line.sku)}</strong><small>${esc(line.sku)} · ${esc(p?.location||'')}</small></td><td class="num">${line.qty}</td>${financial?`<td class="num">${money(line.price)}</td><td class="num">${money(line.discount||0)}</td><td class="num">${money(line.qty*line.price-(line.discount||0))}</td>`:''}</tr>`}).join('');
  const contact=`<section class="oe-detail-card"><span class="eyebrow">ผู้รับและที่อยู่จัดส่ง</span><h3>${esc(order.customer)}</h3><p class="oe-detail-phone">${order.phone?esc(order.phone):'ไม่มีเบอร์โทรในข้อมูลสาธิตเดิม'}</p><p class="oe-detail-address">${esc(orderAddressText(shipping,order.province+' · ที่อยู่สาธิตเดิมยังไม่ครบ'))}</p>${financial&&order.email?`<p>อีเมล: ${esc(order.email)}</p>`:''}${financial&&order.socialName?`<p>โซเชียล: ${esc(order.socialName)}</p>`:''}${financial&&order.socialUrl?`<p class="oe-wrap">ลิงก์: ${esc(order.socialUrl)}</p>`:''}</section>`;
  const status=`<section class="oe-detail-card"><span class="eyebrow">การจัดส่ง</span><div class="oe-detail-status">${badge(order.status)}</div><p>${order.reserved?'กันสินค้าจากสต๊อกกลางแล้ว':'ยังไม่มีจำนวนสินค้าที่กันไว้'}</p><p>ขนส่ง: ${esc(order.carrier||'ยังไม่ระบุ')}<br>เลขติดตาม: ${esc(order.tracking||'ยังไม่มีเลขติดตาม')}</p>${canView('fulfillment')?button('ดูใบจ่าหน้าสาธิต','detail-label','print','small'):''}</section>`;
  const finance=financial?`<div class="oe-detail-finance"><section><h3>ยอดคำสั่งซื้อ</h3><div class="stat-line"><span>ค่าสินค้า</span><strong>${money(totals.subtotal)}</strong></div><div class="stat-line"><span>ส่วนลดรายสินค้า</span><strong>− ${money(totals.lineDiscount)}</strong></div><div class="stat-line"><span>ส่วนลดทั้งออเดอร์</span><strong>− ${money(totals.discount)}</strong></div><div class="stat-line"><span>ค่าจัดส่ง</span><strong>${money(totals.shippingFee)}</strong></div><div class="stat-line total"><span>ยอดที่ต้องชำระ</span><strong>${money(order.grandTotal??totals.grandTotal)}</strong></div>${order.refund?`<div class="stat-line"><span>เงินคืนสินค้า</span><strong>${money(order.refund)}</strong></div>`:''}</section><section><h3>ข้อมูลการชำระ</h3>${payment?`<p>${esc({transfer:'โอนเงิน',cod:'เก็บเงินปลายทาง',unpaid:'ยังไม่ชำระ',free:'ส่งฟรี Review'}[payment.method]||payment.method)} · ${payment.method==='free'?'ไม่มีการรับเงิน':payment.status==='confirmed'?'ยืนยันด้วยตนเองแล้ว':'รอตรวจ / ยังไม่ได้รับเงิน'}</p><div class="stat-line"><span>ยอดรับชำระที่บันทึก</span><strong>${money(payment.amount||0)}</strong></div>${payment.paidAt?`<p>เวลาชำระ: ${esc(orderLocalTime(payment.paidAt).replace('T',' '))} (ไทย)</p>`:''}${payment.bankName?`<p>ธนาคาร: ${esc(payment.bankName)}</p>`:''}${payment.reference?`<p class="oe-wrap">อ้างอิง: ${esc(payment.reference)}</p>`:''}<p class="form-help">ข้อมูลบันทึกโดยผู้ใช้ ไม่มีผลตรวจสลิปหรือการยืนยันจากธนาคาร</p>`:'<p class="form-help">ข้อมูลสาธิตเดิมไม่มีรายละเอียดการชำระเงินรายออเดอร์</p>'}</section></div>`:'';
  const billing=financial&&order.billingSame===false&&order.billingAddress?`<section class="oe-detail-card oe-detail-billing"><h3>ที่อยู่ออกบิล</h3><p>${esc(orderAddressText(order.billingAddress))}</p></section>`:'';
  modal(esc(order.id),esc(order.channel+' · '+formatDate(order.date)),`<div class="oe-detail-top">${contact}${status}</div>${billing}<div class="table-scroll"><table class="data-table oe-detail-items"><thead><tr><th>สินค้า / SKU</th><th class="num">จำนวน</th>${financial?'<th class="num">ราคา / ชิ้น</th><th class="num">ส่วนลดรายการ</th><th class="num">รวม</th>':''}</tr></thead><tbody>${lines}</tbody></table></div>${finance}${order.notes?`<section class="oe-detail-card oe-notes"><h3>หมายเหตุ</h3><p>${esc(order.notes)}</p></section>`:''}${order.tags?`<p class="oe-detail-tags">แท็ก: ${esc(Array.isArray(order.tags)?order.tags.join(', '):order.tags)}</p>`:''}<h3>ประวัติการทำงาน</h3><div class="timeline">${recentLog(order.id).slice().reverse().map(entry=>`<article>${esc(entry.text)}<small>${esc(entry.time)} · ${esc(entry.actor)}</small></article>`).join('')||'<article>ออเดอร์จากชุดข้อมูลสาธิตเริ่มต้น</article>'}</div><div class="modal-actions">${edit}${actions}</div>`);
  orderEditorDialogClass('order-detail-dialog');document.getElementById('edit-order-details')?.addEventListener('click',()=>editOrder(order.id));
};
shippingLabel=function(order){if(!order||!canView('fulfillment'))return;modal('ใบจ่าหน้าสาธิต',esc(order.id),`<div class="demo-label">SAMPLE · ใช้จัดส่งจริงไม่ได้</div><div class="shipping-label oe-shipping-label"><strong>${esc(order.carrier||'ยังไม่ระบุขนส่ง')}</strong><h3>ผู้รับ: ${esc(order.customer)}</h3><p>โทร. ${esc(order.phone||'ไม่มีเบอร์โทรในข้อมูลสาธิตเดิม')}</p><p class="oe-detail-address">${esc(orderAddressText(order.shippingAddress,order.province+' · ที่อยู่สาธิตเดิมยังไม่ครบ'))}</p><hr><strong>${esc(order.id)}</strong><p>${esc(order.tracking||'ยังไม่มีเลขติดตามสาธิต')}<br>${sum(order.items,line=>line.qty)} ชิ้น</p><ul>${order.items.map(line=>`<li>${esc(line.sku)} × ${line.qty}</li>`).join('')}</ul><div class="fake-code" aria-hidden="true"></div><p class="oe-label-warning">DEMO — NOT A SHIPPING BARCODE</p></div><p class="form-help">เป็นตัวอย่างข้อมูลใบจ่าหน้า เลขติดตาม DEMO และบาร์โค้ดนี้ใช้ส่งจริงไม่ได้ ใบจ่าหน้าจริงต้องสร้างจากขนส่งหรือแพลตฟอร์มที่ร้านมีสิทธิ์</p><div class="modal-actions">${button('พิมพ์ตัวอย่าง','print-label','print','primary')}</div>`)};
